# Regenerate sheet1.xml using template styles/structures with answer values
import re, openpyxl
t = open('extracted/xl/worksheets/sheet1.xml', encoding='utf-8').read()

wb = openpyxl.load_workbook('answer.xlsx', data_only=False)
ws = wb['Sheet1']
answers = {}
for r in range(2,72):
    for col in 'BCDEFGHI':
        answers[f'{col}{r}'] = ws[f'{col}{r}'].value

def esc(s):
    return s.replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')

# Parse rows with regex capturing entire row element
row_pat = re.compile(r'<row r="(\d+)"([^>]*)>(.*?)</row>', re.S)

def make_inner(ref, value):
    coord = ref
    if value is None:
        # preserve original empty style if any, handled by using style in attr from original; but if no original cell, omit.
        return None, None
    if isinstance(value, str) and value.startswith('='):
        formula = value[1:]
        return f'<f>{esc(formula)}</f><v></v>', None
    else:
        sv = str(value)
        return f'<is><t xml:space="preserve">{esc(sv)}</t></is>', 'inlineStr'

def rebuild_row(row_xml, ri):
    # get A cell xml and existing B..I cells with styles
    cells = re.findall(r'<c r="([A-Z]+)(\d+)"([^>]*?)(?:/>|>(.*?)</c>)', row_xml, re.S)
    orig_cells = {}
    for col, rr, attrs, inner in cells:
        orig_cells[col] = (attrs, inner)
    # build A cell: keep original A exactly
    out = ''
    a = re.search(r'<c r="A\d+".*?(?:/>|>.*?</c>)', row_xml, re.S)
    if a:
        out += a.group(0)
    for col in 'BCDEFGHI':
        ref=f'{col}{ri}'
        value = answers.get(ref)
        # determine style: use original attrs if cell existed (for B,C,D,I and formula E sometimes no attrs)
        # For cells that did not exist originally but have value, use no style
        attrs = ''
        if col in orig_cells:
            # extract s attr from original attrs
            sm = re.search(r's="(\d+)"', orig_cells[col][0])
            if sm:
                attrs = f' s="{sm.group(1)}"'
            # preserve other attrs? Original B,C,D,I have s only plus t. Original E formula cells have no s. We'll keep s only.
        # But original E cells have no style, D cells styles etc.
        # For cells that did not exist (like D2,E2,F,G,H) attrs='' -> no style.
        if value is None:
            if col in orig_cells:
                # keep original empty cell with style and t=n (to preserve formatting)
                s = re.search(r's="(\d+)"', orig_cells[col][0])
                if s:
                    out += f'<c r="{ref}" s="{s.group(1)}"/>'
                else:
                    out += f'<c r="{ref}"/>'
            continue
        inner, tval = make_inner(ref, value)
        if tval:
            out += f'<c r="{ref}"{attrs} t="inlineStr">{inner}</c>'
        else:
            out += f'<c r="{ref}"{attrs}>{inner}</c>'
    return out

out_rows=[]
for m in row_pat.finditer(t):
    ri=int(m.group(1)); attrs=m.group(2); body=m.group(3)
    if ri==1:
        out_rows.append(m.group(0))
    elif 2 <= ri <= 71:
        out_rows.append(f'<row r="{ri}"{attrs}>{rebuild_row(m.group(0), ri)}</row>')
    else:
        out_rows.append(m.group(0))

sheetdata=''.join(out_rows)
new_t = t.replace(re.search(r'<sheetData>.*?</sheetData>', t, re.S).group(0), '<sheetData>'+sheetdata+'</sheetData>')
open('ans_ext/xl/worksheets/sheet1_new.xml','w',encoding='utf-8').write(new_t)
print('written')
# print some rows
for m in row_pat.finditer(new_t):
    ri=int(m.group(1))
    if ri in (2,3,4,9,21):
        print(m.group(0))
